const e = $input.first().json;
const exec = e.execution || {};

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const workflowName = (e.workflow && e.workflow.name) || 'Unknown workflow';
const node = exec.lastNodeExecuted || 'Unknown node';
const message = (exec.error && exec.error.message) || 'No error message provided';
const url = exec.url || '';

const subject = `[ALERT] ${workflowName} failed at "${node}"`.replace(/[\r\n]+/g, ' ');

const html = `
<div style="font-family:Arial,sans-serif;font-size:14px">
  <h2 style="margin:0 0 8px;color:#b00020">Lead intake failure</h2>
  <p>A submission may not have been saved or notified. Please check it manually.</p>
  <table>
    <tr><td style="padding:4px 12px 4px 0"><b>Workflow</b></td><td>${esc(workflowName)}</td></tr>
    <tr><td style="padding:4px 12px 4px 0"><b>Failed node</b></td><td>${esc(node)}</td></tr>
    <tr><td style="padding:4px 12px 4px 0"><b>Error</b></td><td>${esc(message)}</td></tr>
    <tr><td style="padding:4px 12px 4px 0"><b>Execution ID</b></td><td>${esc(exec.id || 'n/a')}</td></tr>
    <tr><td style="padding:4px 12px 4px 0"><b>Time (UTC)</b></td><td>${new Date().toISOString()}</td></tr>
  </table>
  ${url ? `<p><a href="${esc(url)}">Open the failed execution in n8n</a> to see the lead's data.</p>` : ''}
</div>`;

return [{ json: { to: 'youremail@example.com', subject, html } }];
